(
  _TerminologyOverlay as typeof _TerminologyOverlay & { displayName: string }
).displayName = 'TerminologyOverlay';

/**
 * The `TerminologyOverlay` allows explaining some content in an additional overlay.
 * The element is marked, and a click opens the overlay. The `TerminologyOverlay`
 * consists of at least two elements, its trigger and the corresponding description.
 */
export const TerminologyOverlay = Object.assign(_TerminologyOverlay, {
  Description,
  Trigger,
  Footer,
});
